    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->vinculada_id = null;
        $this->usuario_id = null;
        $this->descripcion = null;
        $this->ruta = null;
        $this->fecha_creacion = null;
        $this->folios = null;
        $this->aceptado = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collTransferencias) {
                foreach ($this->collTransferencias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aUsuario instanceof Persistent) {
              $this->aUsuario->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collTransferencias instanceof PropelCollection) {
            $this->collTransferencias->clearIterator();
        }
        $this->collTransferencias = null;
        $this->aUsuario = null;
    }

